'use client';

import { useRef, useEffect, useCallback, useState } from 'react';

interface EditableTextProps {
  value: string;
  onChange: (value: string) => void;
  tag?: 'p' | 'h1' | 'h2' | 'h3' | 'div' | 'span';
  className?: string;
  placeholder?: string;
  multiline?: boolean;
}

export function EditableText({
  value,
  onChange,
  tag: Tag = 'div',
  className = '',
  placeholder = 'Click to edit...',
  multiline = true,
}: EditableTextProps) {
  const ref = useRef<HTMLElement>(null);
  const idleTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
  const lastValueRef = useRef(value);
  const [isFocused, setIsFocused] = useState(false);

  // Update content when value changes externally (not during editing)
  useEffect(() => {
    if (!isFocused && ref.current && ref.current.textContent !== value) {
      ref.current.textContent = value;
      lastValueRef.current = value;
    }
  }, [value, isFocused]);

  const save = useCallback(() => {
    if (ref.current) {
      const text = ref.current.textContent || '';
      if (text !== lastValueRef.current) {
        lastValueRef.current = text;
        onChange(text);
      }
    }
  }, [onChange]);

  const handleInput = useCallback(() => {
    if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
    idleTimerRef.current = setTimeout(save, 2000);
  }, [save]);

  const handleBlur = useCallback(() => {
    if (idleTimerRef.current) clearTimeout(idleTimerRef.current);
    save();
    setIsFocused(false);
  }, [save]);

  const handleFocus = useCallback(() => {
    setIsFocused(true);
  }, []);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!multiline && e.key === 'Enter') {
        e.preventDefault();
        (e.target as HTMLElement).blur();
      }
    },
    [multiline],
  );

  const isEmpty = !value;

  return (
    <Tag
      ref={ref as React.RefObject<any>}
      contentEditable
      suppressContentEditableWarning
      onInput={handleInput}
      onBlur={handleBlur}
      onFocus={handleFocus}
      onKeyDown={handleKeyDown}
      className={`outline-none focus:ring-2 focus:ring-[#9F80DA]/30 focus:rounded-sm transition-shadow ${
        isEmpty && !isFocused ? 'text-gray-400' : ''
      } ${className}`}
      data-placeholder={placeholder}
    >
      {isEmpty && !isFocused ? placeholder : value}
    </Tag>
  );
}
