'use client';

import { useCallback, useState } from 'react';
import { Plus, Trash2, Image as ImageIcon } from 'lucide-react';
import { EditableText } from './EditableText';
import { CourseComponent } from './CourseComponent';
import { ImagePickerModal } from './ImagePickerModal';
import { KnowledgeCheckEditor } from './KnowledgeCheckEditor';
import type { UnitComponent } from './types';

interface EditableCourseComponentProps {
  component: UnitComponent;
  onDataChange: (data: Record<string, unknown>) => void;
}

export function EditableCourseComponent({
  component,
  onDataChange,
}: EditableCourseComponentProps) {
  const { componentName, content } = component;

  const updateField = useCallback(
    (field: string, value: unknown) => {
      onDataChange({ ...content, [field]: value });
    },
    [content, onDataChange],
  );

  // Text-based blocks: inline contentEditable
  if (isTextBlock(componentName)) {
    return (
      <TextBlockEditor
        componentName={componentName}
        content={content}
        onFieldChange={updateField}
      />
    );
  }

  // List-based blocks: editable items
  if (isListBlock(componentName)) {
    return (
      <ListBlockEditor
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Image blocks: click to open image picker
  if (isImageBlock(componentName)) {
    return (
      <ImageBlockEditor
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
        onFieldChange={updateField}
      />
    );
  }

  // Accordion: inline editing with add/remove
  if (componentName === 'AccordionBlock') {
    return (
      <AccordionEditor content={content} onDataChange={onDataChange} />
    );
  }

  // Tabs: inline editing with add/remove
  if (componentName === 'TabsBlock') {
    return (
      <TabsEditor content={content} onDataChange={onDataChange} />
    );
  }

  // Carousel: image management
  if (componentName === 'CarouselBlock') {
    return (
      <CarouselEditor content={content} onDataChange={onDataChange} />
    );
  }

  // Comparison blocks: editable pairs/items
  if (componentName.startsWith('Comparison')) {
    return (
      <ComparisonEditor
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
        onFieldChange={updateField}
      />
    );
  }

  // Knowledge check blocks: click to open popup editor
  if (isKnowledgeCheckBlock(componentName)) {
    return (
      <KnowledgeCheckBlockEditor
        componentName={componentName}
        component={component}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Default: show read-only
  return <CourseComponent component={component} />;
}

// ─── Category Checks ───────────────────────────────────────────────

function isTextBlock(name: string): boolean {
  return [
    'ParagraphBlock',
    'ParagraphWithHeadingBlock',
    'ParagraphWithSubheadingBlock',
    'HeadingBlock',
    'SubheadingBlock',
    'HighlightBlock',
    'HighlightNoteBlock',
    'HighlightColumnBlock',
    'HighlightCenterLineBlock',
    'HighlightLeftLineBlock',
    'HighlightBackgroundBlock',
    'QuoteBlock',
    'QuoteCenterBorderBlock',
    'QuoteCenterLightBlock',
    'QuoteLeftLightBlock',
    'QuoteLeftBlock',
    'QuoteImageBlock',
  ].includes(name);
}

function isListBlock(name: string): boolean {
  return ['ListBlock', 'CheckboxBlock'].includes(name);
}

function isImageBlock(name: string): boolean {
  return [
    'ImageBlock',
    'ImageWithTextBlock',
    'ImageWithTextLeftBlock',
    'ImageWithTextCenterBlock',
    'ImageWithTextBottomBlock',
    'ImageWithTextTopBlock',
  ].includes(name);
}

function isKnowledgeCheckBlock(name: string): boolean {
  return [
    'MultipleChoiceBlock',
    'MultipleResponseBlock',
    'FillInTheBlankBlock',
    'MatchingPairsBlock',
    'SortingBlock',
    'SortingStepsBlock',
  ].includes(name);
}

// ─── Text Block Editor ─────────────────────────────────────────────

function TextBlockEditor({
  componentName,
  content,
  onFieldChange,
}: {
  componentName: string;
  content: Record<string, unknown>;
  onFieldChange: (field: string, value: unknown) => void;
}) {
  if (componentName === 'ParagraphBlock') {
    return (
      <div className="py-6 px-6">
        <EditableText
          value={String(content.text || '')}
          onChange={(v) => onFieldChange('text', v)}
          tag="p"
          className="text-base text-gray-700 leading-relaxed"
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'ParagraphWithHeadingBlock') {
    return (
      <div className="py-6 px-6 space-y-3">
        <EditableText
          value={String(content.heading || '')}
          onChange={(v) => onFieldChange('heading', v)}
          tag="h2"
          className="text-2xl font-bold text-[#1a1a1a]"
          placeholder="Enter heading..."
          multiline={false}
        />
        <EditableText
          value={String(content.text || '')}
          onChange={(v) => onFieldChange('text', v)}
          tag="p"
          className="text-base text-gray-700 leading-relaxed"
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'ParagraphWithSubheadingBlock') {
    return (
      <div className="py-6 px-6 space-y-3">
        <EditableText
          value={String(content.subheading || '')}
          onChange={(v) => onFieldChange('subheading', v)}
          tag="h3"
          className="text-xl font-semibold text-[#1a1a1a]"
          placeholder="Enter subheading..."
          multiline={false}
        />
        <EditableText
          value={String(content.text || '')}
          onChange={(v) => onFieldChange('text', v)}
          tag="p"
          className="text-base text-gray-700 leading-relaxed"
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'HeadingBlock') {
    return (
      <div className="py-6 px-6">
        <EditableText
          value={String(content.heading || '')}
          onChange={(v) => onFieldChange('heading', v)}
          tag="h1"
          className="text-3xl font-bold text-[#1a1a1a]"
          placeholder="Enter heading..."
          multiline={false}
        />
      </div>
    );
  }

  if (componentName === 'SubheadingBlock') {
    return (
      <div className="py-6 px-6">
        <EditableText
          value={String(content.subheading || content.heading || '')}
          onChange={(v) => onFieldChange(content.subheading !== undefined ? 'subheading' : 'heading', v)}
          tag="h2"
          className="text-2xl font-semibold text-[#1a1a1a]"
          placeholder="Enter subheading..."
          multiline={false}
        />
      </div>
    );
  }

  if (componentName.startsWith('Highlight')) {
    return (
      <div className="py-6 px-6 bg-amber-50 border-l-4 border-amber-400 rounded-r-lg">
        {content.title !== undefined && (
          <EditableText
            value={String(content.title || '')}
            onChange={(v) => onFieldChange('title', v)}
            tag="h3"
            className="text-lg font-semibold text-amber-800 mb-2"
            placeholder="Enter highlight title..."
            multiline={false}
          />
        )}
        <EditableText
          value={String(content.text || content.content || '')}
          onChange={(v) => onFieldChange(content.text !== undefined ? 'text' : 'content', v)}
          tag="p"
          className="text-base text-amber-900"
          placeholder="Enter highlight text..."
        />
      </div>
    );
  }

  if (componentName.startsWith('Quote')) {
    return (
      <div className="py-6 px-6 border-l-4 border-green-400 bg-green-50 rounded-r-lg">
        <EditableText
          value={String(content.quote || content.text || '')}
          onChange={(v) => onFieldChange(content.quote !== undefined ? 'quote' : 'text', v)}
          tag="p"
          className="text-lg italic text-green-900"
          placeholder="Enter quote text..."
        />
        {(content.author !== undefined || content.attribution !== undefined) && (
          <EditableText
            value={String(content.author || content.attribution || '')}
            onChange={(v) => onFieldChange(content.author !== undefined ? 'author' : 'attribution', v)}
            tag="span"
            className="text-sm text-green-700 mt-2 block"
            placeholder="Attribution..."
            multiline={false}
          />
        )}
      </div>
    );
  }

  return (
    <div className="py-6 px-6">
      <EditableText
        value={String(content.text || content.content || '')}
        onChange={(v) => onFieldChange('text', v)}
        tag="p"
        className="text-base text-gray-700"
        placeholder="Enter text..."
      />
    </div>
  );
}

// ─── List Block Editor ─────────────────────────────────────────────

function ListBlockEditor({
  componentName,
  content,
  onDataChange,
}: {
  componentName: string;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const items = (content.items as string[]) || [];

  const updateItem = (index: number, value: string) => {
    const newItems = [...items];
    newItems[index] = value;
    onDataChange({ ...content, items: newItems });
  };

  const addItem = () => {
    onDataChange({ ...content, items: [...items, ''] });
  };

  const removeItem = (index: number) => {
    onDataChange({ ...content, items: items.filter((_, i) => i !== index) });
  };

  return (
    <div className="py-6 px-6 space-y-2">
      {content.title !== undefined && (
        <EditableText
          value={String(content.title || '')}
          onChange={(v) => onDataChange({ ...content, title: v })}
          tag="h3"
          className="text-lg font-semibold text-[#1a1a1a] mb-3"
          placeholder="List title..."
          multiline={false}
        />
      )}
      <ul className="space-y-1">
        {items.map((item, idx) => (
          <li key={idx} className="flex items-start gap-2 group/item">
            {componentName === 'CheckboxBlock' ? (
              <input type="checkbox" className="mt-1.5 accent-[#9F80DA]" readOnly />
            ) : (
              <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-gray-400 flex-shrink-0" />
            )}
            <EditableText
              value={item}
              onChange={(v) => updateItem(idx, v)}
              tag="span"
              className="flex-1 text-base text-gray-700"
              placeholder="Enter list item..."
              multiline={false}
            />
            <button
              onClick={() => removeItem(idx)}
              className="opacity-0 group-hover/item:opacity-100 text-red-400 hover:text-red-600 text-sm transition-opacity"
            >
              ×
            </button>
          </li>
        ))}
      </ul>
      <button
        onClick={addItem}
        className="text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium mt-2"
      >
        + Add item
      </button>
    </div>
  );
}

// ─── Image Block Editor ────────────────────────────────────────────

function ImageBlockEditor({
  componentName,
  content,
  onDataChange,
  onFieldChange,
}: {
  componentName: string;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
  onFieldChange: (field: string, value: unknown) => void;
}) {
  const [showPicker, setShowPicker] = useState(false);
  const imageUrl = String(content.image || '');
  const hasText = componentName !== 'ImageBlock';

  return (
    <>
      <div className="py-4 px-6">
        {/* Image with click-to-change overlay */}
        <div
          className="relative group/img cursor-pointer rounded-lg overflow-hidden"
          onClick={() => setShowPicker(true)}
        >
          {imageUrl ? (
            <img
              src={imageUrl}
              alt={String(content.alt || '')}
              className="w-full h-48 object-cover"
            />
          ) : (
            <div className="w-full h-48 bg-gray-100 flex items-center justify-center">
              <ImageIcon className="w-8 h-8 text-gray-300" />
            </div>
          )}
          <div className="absolute inset-0 bg-black/0 group-hover/img:bg-black/30 transition-colors flex items-center justify-center">
            <span className="px-3 py-1.5 bg-white/90 text-sm text-gray-600 rounded-lg shadow-sm border border-gray-200 opacity-0 group-hover/img:opacity-100 transition-opacity">
              Change image
            </span>
          </div>
        </div>

        {/* Text field for ImageWithText variants */}
        {hasText && (
          <div className="mt-3">
            <EditableText
              value={String(content.text || '')}
              onChange={(v) => onFieldChange('text', v)}
              tag="p"
              className="text-base text-gray-700 leading-relaxed"
              placeholder="Enter image description..."
            />
          </div>
        )}
      </div>

      {showPicker && (
        <ImagePickerModal
          currentUrl={imageUrl}
          onSelect={(url) => onFieldChange('image', url)}
          onClose={() => setShowPicker(false)}
        />
      )}
    </>
  );
}

// ─── Accordion Editor ──────────────────────────────────────────────

function AccordionEditor({
  content,
  onDataChange,
}: {
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const items = (content.items as Array<{ id: string; title: string; content: string }>) || [];

  const updateItem = (index: number, field: string, value: string) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    onDataChange({ ...content, items: newItems });
  };

  const addItem = () => {
    const newId = `acc-${Date.now()}`;
    onDataChange({
      ...content,
      items: [...items, { id: newId, title: '', content: '' }],
    });
  };

  const removeItem = (index: number) => {
    onDataChange({ ...content, items: items.filter((_, i) => i !== index) });
  };

  return (
    <div className="py-4 px-6 space-y-3">
      {items.map((item, idx) => (
        <div key={item.id || idx} className="border border-gray-200 rounded-lg p-3 group/acc">
          <div className="flex items-center gap-2">
            <div className="flex-1">
              <EditableText
                value={item.title}
                onChange={(v) => updateItem(idx, 'title', v)}
                tag="h4"
                className="font-semibold text-[#1a1a1a]"
                placeholder="Accordion title..."
                multiline={false}
              />
            </div>
            <button
              onClick={() => removeItem(idx)}
              className="opacity-0 group-hover/acc:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
          <div className="mt-2 pl-1">
            <EditableText
              value={item.content}
              onChange={(v) => updateItem(idx, 'content', v)}
              tag="p"
              className="text-sm text-gray-600 leading-relaxed"
              placeholder="Accordion content..."
            />
          </div>
        </div>
      ))}
      <button
        onClick={addItem}
        className="flex items-center gap-1 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
      >
        <Plus className="w-4 h-4" />
        Add item
      </button>
    </div>
  );
}

