// ─── Carousel Editor ───────────────────────────────────────────────

function CarouselEditor({
  content,
  onDataChange,
}: {
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const images = (content.images as Array<{ src: string; alt?: string; caption?: string }>) || [];
  const [pickerIndex, setPickerIndex] = useState<number | null>(null);

  const updateImage = (index: number, field: string, value: string) => {
    const newImages = [...images];
    newImages[index] = { ...newImages[index], [field]: value };
    onDataChange({ ...content, images: newImages });
  };

  const addImage = () => {
    onDataChange({
      ...content,
      images: [...images, { src: '', alt: '', caption: '' }],
    });
  };

  const removeImage = (index: number) => {
    onDataChange({ ...content, images: images.filter((_, i) => i !== index) });
  };

  return (
    <>
      <div className="py-4 px-6 space-y-3">
        <div className="grid grid-cols-3 gap-3">
          {images.map((img, idx) => (
            <div key={idx} className="relative group/img border border-gray-200 rounded-lg overflow-hidden">
              <div
                className="h-24 bg-gray-100 cursor-pointer"
                onClick={() => setPickerIndex(idx)}
              >
                {img.src ? (
                  <img src={img.src} alt={img.alt || ''} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <ImageIcon className="w-6 h-6 text-gray-300" />
                  </div>
                )}
              </div>
              <button
                onClick={() => removeImage(idx)}
                className="absolute top-1 right-1 p-1 bg-white/80 rounded-full opacity-0 group-hover/img:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={addImage}
          className="flex items-center gap-1 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          <Plus className="w-4 h-4" />
          Add image
        </button>
      </div>

      {pickerIndex !== null && (
        <ImagePickerModal
          currentUrl={images[pickerIndex]?.src}
          onSelect={(url) => {
            updateImage(pickerIndex, 'src', url);
            setPickerIndex(null);
          }}
          onClose={() => setPickerIndex(null)}
        />
      )}
    </>
  );
}

// ─── Comparison Editor ─────────────────────────────────────────────

function ComparisonEditor({
  componentName,
  content,
  onDataChange,
  onFieldChange,
}: {
  componentName: string;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
  onFieldChange: (field: string, value: unknown) => void;
}) {
  // ComparisonBlock: items array with title/content
  if (componentName === 'ComparisonBlock') {
    const items = (content.items as Array<{ title: string; content: string }>) || [];
    return (
      <div className="py-4 px-6 space-y-3">
        {items.map((item, idx) => (
          <div key={idx} className="border border-gray-200 rounded-lg p-3 group/comp">
            <div className="flex items-start gap-2">
              <div className="flex-1 space-y-2">
                <EditableText
                  value={item.title}
                  onChange={(v) => {
                    const newItems = [...items];
                    newItems[idx] = { ...newItems[idx], title: v };
                    onDataChange({ ...content, items: newItems });
                  }}
                  tag="h4"
                  className="font-semibold text-[#1a1a1a]"
                  placeholder="Item title..."
                  multiline={false}
                />
                <EditableText
                  value={item.content}
                  onChange={(v) => {
                    const newItems = [...items];
                    newItems[idx] = { ...newItems[idx], content: v };
                    onDataChange({ ...content, items: newItems });
                  }}
                  tag="p"
                  className="text-sm text-gray-600"
                  placeholder="Item content..."
                />
              </div>
              <button
                onClick={() => {
                  onDataChange({ ...content, items: items.filter((_, i) => i !== idx) });
                }}
                className="opacity-0 group-hover/comp:opacity-100 p-1 text-red-400 hover:text-red-600 transition-opacity"
              >
                <Trash2 className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        ))}
        <button
          onClick={() => onDataChange({ ...content, items: [...items, { title: '', content: '' }] })}
          className="flex items-center gap-1 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          <Plus className="w-4 h-4" />
          Add item
        </button>
      </div>
    );
  }

  // Two-text-field comparison blocks (CauseEffect, MythFact)
  if (componentName === 'ComparisonCauseEffectBlock') {
    return <TwoFieldEditor content={content} fieldA="cause" fieldB="effect" labelA="Cause" labelB="Effect" onFieldChange={onFieldChange} />;
  }
  if (componentName === 'ComparisonMythFactBlock') {
    return <TwoFieldEditor content={content} fieldA="myth" fieldB="fact" labelA="Myth" labelB="Fact" onFieldChange={onFieldChange} />;
  }

  // Two-list comparison blocks (ProsCons, DosDonts, BeforeAfter)
  if (componentName === 'ComparisonProsConsBlock') {
    return <TwoListEditor content={content} fieldA="pros" fieldB="cons" labelA="Pros" labelB="Cons" onDataChange={onDataChange} />;
  }
  if (componentName === 'ComparisonDosDontsBlock') {
    return <TwoListEditor content={content} fieldA="dos" fieldB="donts" labelA="Do's" labelB="Don'ts" onDataChange={onDataChange} />;
  }
  if (componentName === 'ComparisonBeforeAfterBlock') {
    return <TwoListEditor content={content} fieldA="beforeItems" fieldB="afterItems" labelA="Before" labelB="After" onDataChange={onDataChange} />;
  }

  // Fallback for unknown comparison types
  return <CourseComponent component={{ componentName, content, order: 0, styles: undefined }} />;
}

function TwoFieldEditor({
  content,
  fieldA,
  fieldB,
  labelA,
  labelB,
  onFieldChange,
}: {
  content: Record<string, unknown>;
  fieldA: string;
  fieldB: string;
  labelA: string;
  labelB: string;
  onFieldChange: (field: string, value: unknown) => void;
}) {
  return (
    <div className="py-4 px-6 grid grid-cols-2 gap-4">
      <div className="space-y-2">
        <span className="text-xs font-medium text-gray-500 uppercase">{labelA}</span>
        <EditableText
          value={String(content[fieldA] || '')}
          onChange={(v) => onFieldChange(fieldA, v)}
          tag="p"
          className="text-sm text-gray-700"
          placeholder={`Enter ${labelA.toLowerCase()}...`}
        />
      </div>
      <div className="space-y-2">
        <span className="text-xs font-medium text-gray-500 uppercase">{labelB}</span>
        <EditableText
          value={String(content[fieldB] || '')}
          onChange={(v) => onFieldChange(fieldB, v)}
          tag="p"
          className="text-sm text-gray-700"
          placeholder={`Enter ${labelB.toLowerCase()}...`}
        />
      </div>
    </div>
  );
}

function TwoListEditor({
  content,
  fieldA,
  fieldB,
  labelA,
  labelB,
  onDataChange,
}: {
  content: Record<string, unknown>;
  fieldA: string;
  fieldB: string;
  labelA: string;
  labelB: string;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const listA = (content[fieldA] as string[]) || [];
  const listB = (content[fieldB] as string[]) || [];

  const updateList = (field: string, list: string[], index: number, value: string) => {
    const newList = [...list];
    newList[index] = value;
    onDataChange({ ...content, [field]: newList });
  };

  const addToList = (field: string, list: string[]) => {
    onDataChange({ ...content, [field]: [...list, ''] });
  };

  const removeFromList = (field: string, list: string[], index: number) => {
    onDataChange({ ...content, [field]: list.filter((_, i) => i !== index) });
  };

  return (
    <div className="py-4 px-6 grid grid-cols-2 gap-4">
      <div className="space-y-2">
        <span className="text-xs font-medium text-gray-500 uppercase">{labelA}</span>
        {listA.map((item, idx) => (
          <div key={idx} className="flex items-center gap-1 group/li">
            <EditableText
              value={item}
              onChange={(v) => updateList(fieldA, listA, idx, v)}
              tag="span"
              className="flex-1 text-sm text-gray-700"
              placeholder={`${labelA} item...`}
              multiline={false}
            />
            <button
              onClick={() => removeFromList(fieldA, listA, idx)}
              className="opacity-0 group-hover/li:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
            >
              ×
            </button>
          </div>
        ))}
        <button
          onClick={() => addToList(fieldA, listA)}
          className="text-xs text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          + Add
        </button>
      </div>
      <div className="space-y-2">
        <span className="text-xs font-medium text-gray-500 uppercase">{labelB}</span>
        {listB.map((item, idx) => (
          <div key={idx} className="flex items-center gap-1 group/li">
            <EditableText
              value={item}
              onChange={(v) => updateList(fieldB, listB, idx, v)}
              tag="span"
              className="flex-1 text-sm text-gray-700"
              placeholder={`${labelB} item...`}
              multiline={false}
            />
            <button
              onClick={() => removeFromList(fieldB, listB, idx)}
              className="opacity-0 group-hover/li:opacity-100 text-red-400 hover:text-red-600 transition-opacity"
            >
              ×
            </button>
          </div>
        ))}
        <button
          onClick={() => addToList(fieldB, listB)}
          className="text-xs text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          + Add
        </button>
      </div>
    </div>
  );
}

// ─── Knowledge Check Block Editor ──────────────────────────────────

function KnowledgeCheckBlockEditor({
  componentName,
  component,
  content,
  onDataChange,
}: {
  componentName: string;
  component: UnitComponent;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const [showEditor, setShowEditor] = useState(false);

  return (
    <>
      <div
        className="relative group/kc cursor-pointer"
        onClick={() => setShowEditor(true)}
      >
        <CourseComponent component={component} />
        <div className="absolute inset-0 bg-transparent group-hover/kc:bg-[#9F80DA]/5 transition-colors rounded-lg flex items-center justify-center opacity-0 group-hover/kc:opacity-100">
          <span className="px-3 py-1.5 bg-white/90 text-sm text-gray-600 rounded-lg shadow-sm border border-gray-200">
            Click to edit
          </span>
        </div>
      </div>

      {showEditor && (
        <KnowledgeCheckEditor
          type={componentName as any}
          data={content}
          onSave={onDataChange}
          onClose={() => setShowEditor(false)}
        />
      )}
    </>
  );
}
